Translate the following MS C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <functional>
#include <iomanip>
#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <stack>
#include <queue>
#include <map>
#include <set>
#include <algorithm>
#include <cassert>

using namespace std;

long long solve(long long n) {
    if (n == 0) return 0;
    long long k = 0, cnt = 0;
    while (k * 10 + 1 <= n) {
        k = k * 10 + 1;
        ++cnt;
    }
    long long left = cnt * (n / k) + solve(n % k);
    long long m = 10 * k + 1 - n;
    long long right = cnt + 1 + cnt * (m / k) + solve(m % k);
    return left < right ? left : right;
}

int main() {
#ifndef ONLINE_JUDGE
    assert(freopen("input.txt", "r", stdin));
    assert(freopen("output.txt", "w", stdout));
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    cout << solve(n);
    return 0;
}
</original_code>
